input.contents:
*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  --color-bg: #eef1f5;
  --color-surface: #ffffff;
  --color-surface-muted: #f7f8fa;
  --color-border: #d8dde5;
  --color-border-strong: #b8c0cc;
  --color-text: #1f2937;
  --color-text-muted: #6b7280;
  --color-text-subtle: #9ca3af;
  --color-primary: #2563eb;
  --color-primary-hover: #1d4ed8;
  --color-primary-soft: #eff6ff;
  --color-header: #1e293b;
  --color-header-text: #f8fafc;
  --color-header-muted: #cbd5e1;
  --color-danger: #dc2626;
  --radius-sm: 4px;
  --radius-md: 8px;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.06);
  --shadow-md: 0 4px 12px rgba(15, 23, 42, 0.08);
  --font-sans: 'Segoe UI', system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, 'SF Mono', Consolas, monospace;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  color: var(--color-text);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 100vh;
  background: var(--color-bg);
}

/* Header */

.app-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 20px;
  height: 56px;
  background: var(--color-header);
  color: var(--color-header-text);
  box-shadow: var(--shadow-md);
  flex-shrink: 0;
}

.app-header__brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.app-header__logo {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  background: rgba(255, 255, 255, 0.12);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.app-header__title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.app-header__file-area {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border-radius: var(--radius-md);
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.app-header__file-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-header-muted);
  white-space: nowrap;
}

.app-header__file-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  color: var(--color-header-text);
}

.app-header__file-name--empty {
  color: var(--color-header-muted);
  font-style: italic;
}

.app-header__actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.app-header__file-input {
  display: none;
}

/* Buttons */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  font-size: 13px;
  font-weight: 500;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease;
}

.btn--primary {
  background: var(--color-primary);
  color: #fff;
}

.btn--primary:hover:not(:disabled) {
  background: var(--color-primary-hover);
}

.btn--ghost {
  background: rgba(255, 255, 255, 0.1);
  color: var(--color-header-text);
  border-color: rgba(255, 255, 255, 0.15);
}

.btn--ghost:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.16);
}

.btn--secondary {
  background: var(--color-surface);
  color: var(--color-text);
  border-color: var(--color-border);
}

.btn--secondary:hover:not(:disabled) {
  background: var(--color-surface-muted);
  border-color: var(--color-border-strong);
}

.btn--toggle {
  background: transparent;
  color: var(--color-text-muted);
  border-color: var(--color-border);
}

.btn--toggle.is-active {
  background: var(--color-primary-soft);
  color: var(--color-primary);
  border-color: #bfdbfe;
}

/* Workspace */

.app-workspace {
  display: flex;
  flex: 1;
  min-height: 0;
}

.app-sidebar {
  width: 148px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  background: var(--color-surface);
  border-right: 1px solid var(--color-border);
}

.app-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.app-edit-panel {
  width: 280px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  background: var(--color-surface);
  border-left: 1px solid var(--color-border);
}

/* Toolbars */

.viewer-toolbar,
.editor-toolbar {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 12px;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  flex-shrink: 0;
}

.viewer-toolbar {
  flex-wrap: wrap;
}

.toolbar-group {
  display: flex;
  align-items: center;
  gap: 2px;
}

.toolbar-group + .toolbar-group {
  margin-left: 4px;
  padding-left: 8px;
  border-left: 1px solid var(--color-border);
}

.toolbar-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  height: 32px;
  padding: 0 8px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-text-muted);
  font-size: 12px;
  font-weight: 500;
}

.toolbar-btn:hover:not(:disabled) {
  background: var(--color-surface-muted);
  color: var(--color-text);
  border-color: var(--color-border);
}

.toolbar-btn.is-active {
  background: var(--color-primary-soft);
  color: var(--color-primary);
  border-color: #bfdbfe;
}

.toolbar-label {
  padding: 0 8px;
  font-size: 12px;
  color: var(--color-text-muted);
  white-space: nowrap;
}

.toolbar-spacer {
  flex: 1;
}

/* Thumbnails */

.thumbnail-list {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

.thumbnail-list__header {
  padding: 10px 12px 8px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-text-subtle);
  border-bottom: 1px solid var(--color-border);
}

.thumbnail-list__body {
  flex: 1;
  overflow-y: auto;
  padding: 10px;
}

.thumbnail-list__empty {
  padding: 16px 8px;
  text-align: center;
  font-size: 12px;
  color: var(--color-text-subtle);
  line-height: 1.45;
}

.thumbnail-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: 100%;
  margin-bottom: 10px;
  padding: 6px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-surface-muted);
  cursor: pointer;
  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease;
}

.thumbnail-item:hover {
  border-color: var(--color-border-strong);
}

.thumbnail-item.is-active {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 1px var(--color-primary);
}

.thumbnail-item__preview {
  width: 100%;
  aspect-ratio: 8.5 / 11;
  border-radius: 2px;
  background: linear-gradient(180deg, #fff 0%, #f3f4f6 100%);
  border: 1px solid var(--color-border);
}

.thumbnail-item__label {
  font-size: 11px;
  color: var(--color-text-muted);
}

/* PDF viewer */

.pdf-viewer {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: #525659;
  position: relative;
}

.pdf-viewer__canvas-area {
  flex: 1;
  overflow: auto;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 24px;
}

.pdf-viewer__empty,
.pdf-viewer__placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: min(480px, 100%);
  margin: auto;
  padding: 40px 32px;
  text-align: center;
  border-radius: var(--radius-md);
  border: 2px dashed rgba(255, 255, 255, 0.35);
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.92);
}

.pdf-viewer__empty.is-dragging {
  border-color: #93c5fd;
  background: rgba(37, 99, 235, 0.15);
}

.pdf-viewer__empty-icon {
  font-size: 40px;
  line-height: 1;
  opacity: 0.85;
}

.pdf-viewer__empty-title {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
}

.pdf-viewer__empty-text {
  margin: 0;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.72);
  max-width: 320px;
}

.pdf-viewer__page-shell {
  width: min(820px, 100%);
  aspect-ratio: 8.5 / 11;
  background: #fff;
  box-shadow: var(--shadow-md);
  border-radius: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  font-size: 14px;
}

/* Edit panel */

.edit-panel__header {
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-border);
}

.edit-panel__title {
  margin: 0 0 4px;
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text);
}

.edit-panel__subtitle {
  margin: 0;
  font-size: 12px;
  color: var(--color-text-subtle);
}

.edit-panel__body {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
}

.edit-panel__placeholder {
  padding: 20px 16px;
  border-radius: var(--radius-md);
  border: 1px dashed var(--color-border);
  background: var(--color-surface-muted);
  text-align: center;
}

.edit-panel__placeholder-title {
  margin: 0 0 8px;
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text);
}

.edit-panel__placeholder-text {
  margin: 0;
  font-size: 12px;
  color: var(--color-text-muted);
  line-height: 1.5;
}

.edit-panel__tool-list {
  margin: 16px 0 0;
  padding: 0;
  list-style: none;
  text-align: left;
}

.edit-panel__tool-list li {
  position: relative;
  padding-left: 14px;
  font-size: 12px;
  color: var(--color-text-muted);
  line-height: 1.6;
}

.edit-panel__tool-list li::before {
  content: '•';
  position: absolute;
  left: 0;
  color: var(--color-text-subtle);
}

type PageThumbnailListProps = {
  pageCount?: number
  currentPage?: number
  onPageSelect?: (page: number) => void
}

export default function PageThumbnailList({
  pageCount = 0,
  currentPage = 1,
  onPageSelect,
}: PageThumbnailListProps) {
  const hasDocument = pageCount > 0

  return (
    <aside className="thumbnail-list" aria-label="Page thumbnails">
      <div className="thumbnail-list__header">Pages</div>
      <div className="thumbnail-list__body">
        {!hasDocument ? (
          <p className="thumbnail-list__empty">
            Open a PDF to see page thumbnails.
          </p>
        ) : (
          Array.from({ length: pageCount }, (_, index) => {
            const pageNumber = index + 1
            const isActive = pageNumber === currentPage

            return (
              <button
                key={pageNumber}
                type="button"
                className={`thumbnail-item${isActive ? ' is-active' : ''}`}
                onClick={() => onPageSelect?.(pageNumber)}
                aria-label={`Page ${pageNumber}`}
                aria-current={isActive ? 'page' : undefined}
              >
                <div className="thumbnail-item__preview" aria-hidden="true" />
                <span className="thumbnail-item__label">{pageNumber}</span>
              </button>
            )
          })
        )}
      </div>
    </aside>
  )
}

import { useRef, useState, type DragEvent } from 'react'

type PdfViewerProps = {
  fileName: string | null
  onFileSelect: (file: File) => void
}

export default function PdfViewer({ fileName, onFileSelect }: PdfViewerProps) {
  const inputRef = useRef<HTMLInputElement>(null)
  const [isDragging, setIsDragging] = useState(false)

  const openFilePicker = () => {
    inputRef.current?.click()
  }

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (file) {
      onFileSelect(file)
    }
    event.target.value = ''
  }

  const handleDragOver = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    setIsDragging(true)
  }

  const handleDragLeave = () => {
    setIsDragging(false)
  }

  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    setIsDragging(false)

    const file = event.dataTransfer.files?.[0]
    if (file) {
      onFileSelect(file)
    }
  }

  return (
    <section className="pdf-viewer" aria-label="Document viewer">
      <input
        ref={inputRef}
        type="file"
        accept="application/pdf,.pdf"
        className="app-header__file-input"
        onChange={handleInputChange}
        aria-hidden="true"
        tabIndex={-1}
      />

      <div className="pdf-viewer__canvas-area">
        {!fileName ? (
          <div
            className={`pdf-viewer__empty${isDragging ? ' is-dragging' : ''}`}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
          >
            <div className="pdf-viewer__empty-icon" aria-hidden="true">
              📄
            </div>
            <h2 className="pdf-viewer__empty-title">Open a PDF to begin</h2>
            <p className="pdf-viewer__empty-text">
              Drag and drop a local PDF here, or use Open PDF in the header to
              select a file from your computer.
            </p>
            <button type="button" className="btn btn--primary" onClick={openFilePicker}>
              Choose PDF
            </button>
          </div>
        ) : (
          <div className="pdf-viewer__page-shell" role="img" aria-label={`Preview of ${fileName}`}>
            PDF rendering will appear here
          </div>
        )}
      </div>
    </section>
  )
}

import { useCallback, useRef, useState } from 'react'
import EditorToolbar from './components/EditorToolbar'
import PageThumbnailList from './components/PageThumbnailList'
import PdfViewer from './components/PdfViewer'
import ViewerToolbar from './components/ViewerToolbar'
import './App.css'

function App() {
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [fileName, setFileName] = useState<string | null>(null)
  const [pageCount, setPageCount] = useState(0)
  const [currentPage, setCurrentPage] = useState(1)
  const [isEditMode, setIsEditMode] = useState(false)

  const hasDocument = fileName !== null

  const handleFileSelect = useCallback((file: File) => {
    const isPdf =
      file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf')

    if (!isPdf) {
      window.alert('Please select a PDF file.')
      return
    }

    setFileName(file.name)
    setPageCount(1)
    setCurrentPage(1)
    setIsEditMode(false)
  }, [])

  const openFilePicker = () => {
    fileInputRef.current?.click()
  }

  const handleHeaderFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (file) {
      handleFileSelect(file)
    }
    event.target.value = ''
  }

  const handleQuickDownload = () => {
    if (!hasDocument) {
      return
    }
    window.alert('Quick Download will be available once PDF export is implemented.')
  }

  return (
    <div className="app">
      <header className="app-header">
        <div className="app-header__brand">
          <div className="app-header__logo" aria-hidden="true">
            N
          </div>
          <h1 className="app-header__title">Neubus PDF Viewer</h1>
        </div>

        <div className="app-header__file-area">
          <span className="app-header__file-label">Document</span>
          <span
            className={`app-header__file-name${hasDocument ? '' : ' app-header__file-name--empty'}`}
            title={fileName ?? undefined}
          >
            {fileName ?? 'No file selected'}
          </span>
        </div>

        <div className="app-header__actions">
          <input
            ref={fileInputRef}
            type="file"
            accept="application/pdf,.pdf"
            className="app-header__file-input"
            onChange={handleHeaderFileChange}
            aria-label="Open PDF file"
          />
          <button type="button" className="btn btn--ghost" onClick={openFilePicker}>
            Open PDF
          </button>
          <button
            type="button"
            className="btn btn--primary"
            disabled={!hasDocument}
            onClick={handleQuickDownload}
          >
            Quick Download
          </button>
        </div>
      </header>

      <div className="app-workspace">
        <div className="app-sidebar">
          <PageThumbnailList
            pageCount={pageCount}
            currentPage={currentPage}
            onPageSelect={setCurrentPage}
          />
        </div>

        <main className="app-main">
          <ViewerToolbar
            disabled={!hasDocument}
            currentPage={currentPage}
            pageCount={pageCount}
            isEditMode={isEditMode}
            onToggleEditMode={() => setIsEditMode((value) => !value)}
          />
          <PdfViewer fileName={fileName} onFileSelect={handleFileSelect} />
        </main>

        <aside className="app-edit-panel" aria-label="Edit mode panel">
          <EditorToolbar disabled={!hasDocument || !isEditMode} />

          <div className="edit-panel__header">
            <h2 className="edit-panel__title">Edit mode</h2>
            <p className="edit-panel__subtitle">
              {isEditMode
                ? 'Page editing tools will appear here.'
                : 'Enable edit mode from the viewer toolbar to modify pages.'}
            </p>
          </div>

          <div className="edit-panel__body">
            <div className="edit-panel__placeholder">
              <p className="edit-panel__placeholder-title">Editor panel placeholder</p>
              <p className="edit-panel__placeholder-text">
                This area will host page operations such as rotate, reorder, delete,
                import, extract, and export once editing is implemented.
              </p>
              <ul className="edit-panel__tool-list">
                <li>Rotate selected pages</li>
                <li>Reorder and delete pages</li>
                <li>Import or extract pages</li>
                <li>Export edited PDF</li>
              </ul>
            </div>
          </div>
        </aside>
      </div>
    </div>
  )
}

export default App

