import { getDocument, type PDFDocumentProxy } from 'pdfjs-dist'

export async function loadPdfDocument(data: ArrayBuffer): Promise<PDFDocumentProxy> {
  const loadingTask = getDocument({ data: data.slice(0) })
  return loadingTask.promise
}

import type { PDFDocumentProxy } from 'pdfjs-dist'

export async function renderPageToCanvas(
  pdfDoc: PDFDocumentProxy,
  pageNumber: number,
  canvas: HTMLCanvasElement,
  scale: number,
): Promise<void> {
  const page = await pdfDoc.getPage(pageNumber)
  const viewport = page.getViewport({ scale })
  const outputScale = window.devicePixelRatio || 1

  canvas.width = Math.floor(viewport.width * outputScale)
  canvas.height = Math.floor(viewport.height * outputScale)
  canvas.style.width = `${Math.floor(viewport.width)}px`
  canvas.style.height = `${Math.floor(viewport.height)}px`

  const context = canvas.getContext('2d')
  if (!context) {
    throw new Error('Unable to acquire canvas rendering context.')
  }

  context.setTransform(outputScale, 0, 0, outputScale, 0, 0)
  context.clearRect(0, 0, canvas.width, canvas.height)

  const renderTask = page.render({
    canvasContext: context,
    viewport,
    canvas,
  })

  await renderTask.promise
}

import { useEffect, useRef, useState } from 'react'
import type { PDFDocumentProxy } from 'pdfjs-dist'
import { renderPageToCanvas } from '../lib/pdfjs/renderPage'

type PageCanvasProps = {
  pdfDoc: PDFDocumentProxy
  pageNumber: number
  scale: number
  className?: string
  id?: string
}

export default function PageCanvas({
  pdfDoc,
  pageNumber,
  scale,
  className,
  id,
}: PageCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [renderError, setRenderError] = useState<string | null>(null)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) {
      return
    }

    let cancelled = false
    setRenderError(null)

    renderPageToCanvas(pdfDoc, pageNumber, canvas, scale).catch((error: unknown) => {
      if (!cancelled) {
        const message = error instanceof Error ? error.message : 'Failed to render page.'
        setRenderError(message)
      }
    })

    return () => {
      cancelled = true
    }
  }, [pdfDoc, pageNumber, scale])

  if (renderError) {
    return (
      <div className="pdf-page-canvas pdf-page-canvas--error" id={id}>
        Unable to render page {pageNumber}.
      </div>
    )
  }

  return (
    <canvas
      ref={canvasRef}
      className={className ?? 'pdf-page-canvas'}
      id={id}
      aria-label={`Page ${pageNumber}`}
    />
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import type { PDFDocumentProxy } from 'pdfjs-dist'
import { loadPdfDocument } from '../lib/pdfjs/loadDocument'
import type { LoadStatus } from '../types/pdf'

function isPdfFile(file: File): boolean {
  return file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf')
}

export function usePdfDocument() {
  const pdfDocRef = useRef<PDFDocumentProxy | null>(null)
  const [fileName, setFileName] = useState<string | null>(null)
  const [pdfBytes, setPdfBytes] = useState<ArrayBuffer | null>(null)
  const [pdfDoc, setPdfDoc] = useState<PDFDocumentProxy | null>(null)
  const [pageCount, setPageCount] = useState(0)
  const [loadStatus, setLoadStatus] = useState<LoadStatus>('idle')
  const [loadError, setLoadError] = useState<string | null>(null)

  const destroyDocument = useCallback(async () => {
    const currentDoc = pdfDocRef.current
    pdfDocRef.current = null
    setPdfDoc(null)

    if (currentDoc) {
      await currentDoc.destroy()
    }
  }, [])

  const openFile = useCallback(
    async (file: File) => {
      if (!isPdfFile(file)) {
        window.alert('Please select a PDF file.')
        return
      }

      setLoadStatus('loading')
      setLoadError(null)
      setFileName(file.name)
      setPageCount(0)

      await destroyDocument()

      try {
        const bytes = await file.arrayBuffer()
        const doc = await loadPdfDocument(bytes)

        pdfDocRef.current = doc
        setPdfBytes(bytes)
        setPdfDoc(doc)
        setPageCount(doc.numPages)
        setLoadStatus('ready')
      } catch (error) {
        const message =
          error instanceof Error ? error.message : 'Unable to load the selected PDF.'
        setPdfBytes(null)
        setLoadError(message)
        setLoadStatus('error')
      }
    },
    [destroyDocument],
  )

  useEffect(() => {
    return () => {
      void destroyDocument()
    }
  }, [destroyDocument])

  return {
    fileName,
    pdfBytes,
    pdfDoc,
    pageCount,
    loadStatus,
    loadError,
    openFile,
    hasDocument: loadStatus === 'ready' && pdfDoc !== null,
  }
}

import { useEffect, useRef, useState, type ChangeEvent, type DragEvent } from 'react'
import type { PDFDocumentProxy } from 'pdfjs-dist'
import type { LoadStatus, ViewMode } from '../types/pdf'
import PageCanvas from './PageCanvas'

type PdfViewerProps = {
  fileName: string | null
  pdfDoc: PDFDocumentProxy | null
  loadStatus: LoadStatus
  loadError: string | null
  currentPage: number
  pageCount: number
  viewMode: ViewMode
  scale: number
  onFileSelect: (file: File) => void
}

export default function PdfViewer({
  fileName,
  pdfDoc,
  loadStatus,
  loadError,
  currentPage,
  pageCount,
  viewMode,
  scale,
  onFileSelect,
}: PdfViewerProps) {
  const inputRef = useRef<HTMLInputElement>(null)
  const canvasAreaRef = useRef<HTMLDivElement>(null)
  const [isDragging, setIsDragging] = useState(false)

  useEffect(() => {
    if (viewMode !== 'continuous' || !pdfDoc) {
      return
    }

    const pageElement = document.getElementById(`pdf-page-${currentPage}`)
    pageElement?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }, [currentPage, viewMode, pdfDoc])

  useEffect(() => {
    if (viewMode !== 'single' || !pdfDoc) {
      return
    }

    canvasAreaRef.current?.scrollTo({ top: 0, behavior: 'auto' })
  }, [currentPage, viewMode, pdfDoc])

  const openFilePicker = () => {
    inputRef.current?.click()
  }

  const handleInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (file) {
      onFileSelect(file)
    }
    event.target.value = ''
  }

  const handleDragOver = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    setIsDragging(true)
  }

  const handleDragLeave = () => {
    setIsDragging(false)
  }

  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    setIsDragging(false)

    const file = event.dataTransfer.files?.[0]
    if (file) {
      onFileSelect(file)
    }
  }

  const showEmptyState = loadStatus === 'idle' || (loadStatus === 'error' && !pdfDoc)

  return (
    <section className="pdf-viewer" aria-label="Document viewer">
      <input
        ref={inputRef}
        type="file"
        accept="application/pdf,.pdf"
        className="app-header__file-input"
        onChange={handleInputChange}
        aria-hidden="true"
        tabIndex={-1}
      />

      {loadStatus === 'loading' && (
        <div className="pdf-viewer__status pdf-viewer__status--loading" role="status">
          Loading PDF…
        </div>
      )}

      {loadStatus === 'error' && loadError && (
        <div className="pdf-viewer__status pdf-viewer__status--error" role="alert">
          {loadError}
        </div>
      )}

      <div ref={canvasAreaRef} className="pdf-viewer__canvas-area">
        {showEmptyState ? (
          <div
            className={`pdf-viewer__empty${isDragging ? ' is-dragging' : ''}`}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
          >
            <div className="pdf-viewer__empty-icon" aria-hidden="true">
              PDF
            </div>
            <h2 className="pdf-viewer__empty-title">Open a PDF to begin</h2>
            <p className="pdf-viewer__empty-text">
              Drag and drop a local PDF here, or use Open PDF in the header to
              select a file from your computer.
            </p>
            <button type="button" className="btn btn--primary" onClick={openFilePicker}>
              Choose PDF
            </button>
          </div>
        ) : pdfDoc && loadStatus === 'ready' ? (
          <div className="pdf-viewer__pages">
            {viewMode === 'single' ? (
              <PageCanvas
                key={`single-${currentPage}-${scale}`}
                pdfDoc={pdfDoc}
                pageNumber={currentPage}
                scale={scale}
              />
            ) : (
              Array.from({ length: pageCount }, (_, index) => {
                const pageNumber = index + 1
                return (
                  <PageCanvas
                    key={`continuous-${pageNumber}-${scale}`}
                    id={`pdf-page-${pageNumber}`}
                    pdfDoc={pdfDoc}
                    pageNumber={pageNumber}
                    scale={scale}
                  />
                )
              })
            )}
          </div>
        ) : null}
      </div>

      {fileName && loadStatus === 'ready' && (
        <div className="pdf-viewer__footer" aria-live="polite">
          Viewing {fileName}
        </div>
      )}
    </section>
  )
}

import type { PDFDocumentProxy } from 'pdfjs-dist'
import PageCanvas from './PageCanvas'

type PageThumbnailListProps = {
  pdfDoc?: PDFDocumentProxy | null
  pageCount?: number
  currentPage?: number
  onPageSelect?: (page: number) => void
}

const THUMBNAIL_SCALE = 0.18

export default function PageThumbnailList({
  pdfDoc = null,
  pageCount = 0,
  currentPage = 1,
  onPageSelect,
}: PageThumbnailListProps) {
  const hasDocument = pageCount > 0 && pdfDoc !== null

  return (
    <aside className="thumbnail-list" aria-label="Page thumbnails">
      <div className="thumbnail-list__header">Pages</div>
      <div className="thumbnail-list__body">
        {!hasDocument ? (
          <p className="thumbnail-list__empty">
            Open a PDF to see page thumbnails.
          </p>
        ) : (
          Array.from({ length: pageCount }, (_, index) => {
            const pageNumber = index + 1
            const isActive = pageNumber === currentPage

            return (
              <button
                key={pageNumber}
                type="button"
                className={`thumbnail-item${isActive ? ' is-active' : ''}`}
                onClick={() => onPageSelect?.(pageNumber)}
                aria-label={`Page ${pageNumber}`}
                aria-current={isActive ? 'page' : undefined}
              >
                <div className="thumbnail-item__preview">
                  <PageCanvas
                    pdfDoc={pdfDoc}
                    pageNumber={pageNumber}
                    scale={THUMBNAIL_SCALE}
                    className="thumbnail-item__canvas"
                  />
                </div>
                <span className="thumbnail-item__label">{pageNumber}</span>
              </button>
            )
          })
        )}
      </div>
    </aside>
  )
}

import { useCallback, useRef, useState, type ChangeEvent } from 'react'
import EditorToolbar from './components/EditorToolbar'
import PageThumbnailList from './components/PageThumbnailList'
import PdfViewer from './components/PdfViewer'
import ViewerToolbar from './components/ViewerToolbar'
import { usePdfDocument } from './hooks/usePdfDocument'
import type { ViewMode } from './types/pdf'
import './App.css'

const DEFAULT_SCALE = 1.25

function clampPage(page: number, pageCount: number): number {
  if (pageCount <= 0) {
    return 1
  }
  return Math.min(Math.max(page, 1), pageCount)
}

function App() {
  const fileInputRef = useRef<HTMLInputElement>(null)
  const {
    fileName,
    pdfBytes,
    pdfDoc,
    pageCount,
    loadStatus,
    loadError,
    openFile,
    hasDocument,
  } = usePdfDocument()

  const [currentPage, setCurrentPage] = useState(1)
  const [viewMode, setViewMode] = useState<ViewMode>('continuous')
  const [scale] = useState(DEFAULT_SCALE)
  const [isEditMode, setIsEditMode] = useState(false)

  const handleFileSelect = useCallback(
    async (file: File) => {
      await openFile(file)
      setCurrentPage(1)
      setIsEditMode(false)
    },
    [openFile],
  )

  const openFilePicker = () => {
    fileInputRef.current?.click()
  }

  const handleHeaderFileChange = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (file) {
      void handleFileSelect(file)
    }
    event.target.value = ''
  }

  const handleQuickDownload = () => {
    if (!pdfBytes || !fileName) {
      return
    }

    const blob = new Blob([pdfBytes], { type: 'application/pdf' })
    const url = URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = fileName
    anchor.click()
    URL.revokeObjectURL(url)
  }

  const goToPage = useCallback(
    (page: number) => {
      setCurrentPage(clampPage(page, pageCount))
    },
    [pageCount],
  )

  const goToPreviousPage = () => {
    goToPage(currentPage - 1)
  }

  const goToNextPage = () => {
    goToPage(currentPage + 1)
  }

  return (
    <div className="app">
      <header className="app-header">
        <div className="app-header__brand">
          <div className="app-header__logo" aria-hidden="true">
            N
          </div>
          <h1 className="app-header__title">Neubus PDF Viewer</h1>
        </div>

        <div className="app-header__file-area">
          <span className="app-header__file-label">Document</span>
          <span
            className={`app-header__file-name${hasDocument ? '' : ' app-header__file-name--empty'}`}
            title={fileName ?? undefined}
          >
            {fileName ?? 'No file selected'}
          </span>
        </div>

        <div className="app-header__actions">
          <input
            ref={fileInputRef}
            type="file"
            accept="application/pdf,.pdf"
            className="app-header__file-input"
            onChange={handleHeaderFileChange}
            aria-label="Open PDF file"
          />
          <button type="button" className="btn btn--ghost" onClick={openFilePicker}>
            Open PDF
          </button>
          <button
            type="button"
            className="btn btn--primary"
            disabled={!hasDocument}
            onClick={handleQuickDownload}
          >
            Quick Download
          </button>
        </div>
      </header>

      <div className="app-workspace">
        <div className="app-sidebar">
          <PageThumbnailList
            pdfDoc={pdfDoc}
            pageCount={pageCount}
            currentPage={currentPage}
            onPageSelect={goToPage}
          />
        </div>

        <main className="app-main">
          <ViewerToolbar
            disabled={!hasDocument}
            currentPage={currentPage}
            pageCount={pageCount}
            zoomPercent={Math.round(scale * 100)}
            viewMode={viewMode}
            isEditMode={isEditMode}
            onPreviousPage={goToPreviousPage}
            onNextPage={goToNextPage}
            onPageChange={goToPage}
            onViewModeChange={setViewMode}
            onToggleEditMode={() => setIsEditMode((value) => !value)}
          />
          <PdfViewer
            fileName={fileName}
            pdfDoc={pdfDoc}
            loadStatus={loadStatus}
            loadError={loadError}
            currentPage={currentPage}
            pageCount={pageCount}
            viewMode={viewMode}
            scale={scale}
            onFileSelect={handleFileSelect}
          />
        </main>

        <aside className="app-edit-panel" aria-label="Edit mode panel">
          <EditorToolbar disabled={!hasDocument || !isEditMode} />

          <div className="edit-panel__header">
            <h2 className="edit-panel__title">Edit mode</h2>
            <p className="edit-panel__subtitle">
              {isEditMode
                ? 'Page editing tools will appear here.'
                : 'Enable edit mode from the viewer toolbar to modify pages.'}
            </p>
          </div>

          <div className="edit-panel__body">
            <div className="edit-panel__placeholder">
              <p className="edit-panel__placeholder-title">Editor panel placeholder</p>
              <p className="edit-panel__placeholder-text">
                This area will host page operations such as rotate, reorder, delete,
                import, extract, and export once editing is implemented.
              </p>
              <ul className="edit-panel__tool-list">
                <li>Rotate selected pages</li>
                <li>Reorder and delete pages</li>
                <li>Import or extract pages</li>
                <li>Export edited PDF</li>
              </ul>
            </div>
          </div>
        </aside>
      </div>
    </div>
  )
}

export default App

