import { getDocument, type PDFDocumentLoadingTask, type PDFDocumentProxy } from 'pdfjs-dist'

export type LoadedPdfDocument = {
  doc: PDFDocumentProxy
  loadingTask: PDFDocumentLoadingTask
}

export async function loadPdfDocument(data: ArrayBuffer): Promise<LoadedPdfDocument> {
  const loadingTask = getDocument({ data: data.slice(0) })
  const doc = await loadingTask.promise
  return { doc, loadingTask }
}

import { useCallback, useEffect, useRef, useState } from 'react'
import type { PDFDocumentLoadingTask, PDFDocumentProxy } from 'pdfjs-dist'
import { loadPdfDocument } from '../lib/pdfjs/loadDocument'
import type { LoadStatus } from '../types/pdf'

function isPdfFile(file: File): boolean {
  return file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf')
}

export function usePdfDocument() {
  const loadingTaskRef = useRef<PDFDocumentLoadingTask | null>(null)
  const [fileName, setFileName] = useState<string | null>(null)
  const [pdfBytes, setPdfBytes] = useState<ArrayBuffer | null>(null)
  const [pdfDoc, setPdfDoc] = useState<PDFDocumentProxy | null>(null)
  const [pageCount, setPageCount] = useState(0)
  const [loadStatus, setLoadStatus] = useState<LoadStatus>('idle')
  const [loadError, setLoadError] = useState<string | null>(null)

  const destroyDocument = useCallback(async () => {
    const currentTask = loadingTaskRef.current
    loadingTaskRef.current = null
    setPdfDoc(null)

    if (currentTask) {
      await currentTask.destroy()
    }
  }, [])

  const openFile = useCallback(
    async (file: File) => {
      if (!isPdfFile(file)) {
        window.alert('Please select a PDF file.')
        return
      }

      setLoadStatus('loading')
      setLoadError(null)
      setFileName(file.name)
      setPageCount(0)

      await destroyDocument()

      try {
        const bytes = await file.arrayBuffer()
        const { doc, loadingTask } = await loadPdfDocument(bytes)

        loadingTaskRef.current = loadingTask
        setPdfBytes(bytes)
        setPdfDoc(doc)
        setPageCount(doc.numPages)
        setLoadStatus('ready')
      } catch (error) {
        const message =
          error instanceof Error ? error.message : 'Unable to load the selected PDF.'
        setPdfBytes(null)
        setLoadError(message)
        setLoadStatus('error')
      }
    },
    [destroyDocument],
  )

  useEffect(() => {
    return () => {
      void destroyDocument()
    }
  }, [destroyDocument])

  return {
    fileName,
    pdfBytes,
    pdfDoc,
    pageCount,
    loadStatus,
    loadError,
    openFile,
    hasDocument: loadStatus === 'ready' && pdfDoc !== null,
  }
}

