import { useEffect, useRef, useState } from 'react'
import type { PDFDocumentLoadingTask, PDFDocumentProxy } from 'pdfjs-dist'
import { loadPdfDocument } from '../lib/pdfjs/loadDocument'
import type { LoadStatus } from '../types/pdf'

export type PdfDocumentState = {
  pdfDoc: PDFDocumentProxy | null
  pageCount: number
  loadStatus: LoadStatus
  loadError: string | null
}

const idleDocumentState: PdfDocumentState = {
  pdfDoc: null,
  pageCount: 0,
  loadStatus: 'idle',
  loadError: null,
}

export function usePdfFromBytes(pdfBytes: ArrayBuffer | null): PdfDocumentState {
  const loadingTaskRef = useRef<PDFDocumentLoadingTask | null>(null)
  const [state, setState] = useState<PdfDocumentState>(idleDocumentState)

  useEffect(() => {
    if (!pdfBytes) {
      setState(idleDocumentState)
      return
    }

    let cancelled = false

    setState({
      pdfDoc: null,
      pageCount: 0,
      loadStatus: 'loading',
      loadError: null,
    })

    const loadDocument = async () => {
      const previousTask = loadingTaskRef.current
      loadingTaskRef.current = null

      if (previousTask) {
        await previousTask.destroy()
      }

      try {
        const { doc, loadingTask } = await loadPdfDocument(pdfBytes)

        if (cancelled) {
          await loadingTask.destroy()
          return
        }

        loadingTaskRef.current = loadingTask
        setState({
          pdfDoc: doc,
          pageCount: doc.numPages,
          loadStatus: 'ready',
          loadError: null,
        })
      } catch (error) {
        if (cancelled) {
          return
        }

        const message =
          error instanceof Error ? error.message : 'Unable to load the selected PDF.'

        setState({
          pdfDoc: null,
          pageCount: 0,
          loadStatus: 'error',
          loadError: message,
        })
      }
    }

    void loadDocument()

    return () => {
      cancelled = true
      const activeTask = loadingTaskRef.current
      loadingTaskRef.current = null

      if (activeTask) {
        void activeTask.destroy()
      }
    }
  }, [pdfBytes])

  return state
}

import { useEffect, useRef, useState, type ChangeEvent, type DragEvent } from 'react'
import { usePdfFromBytes, type PdfDocumentState } from '../hooks/usePdfFromBytes'
import type { ViewMode } from '../types/pdf'
import PageCanvas from './PageCanvas'

type PdfViewerProps = {
  fileName: string | null
  pdfBytes: ArrayBuffer | null
  currentPage: number
  viewMode: ViewMode
  scale: number
  onFileSelect: (file: File) => void
  onDocumentStateChange: (state: PdfDocumentState) => void
}

export default function PdfViewer({
  fileName,
  pdfBytes,
  currentPage,
  viewMode,
  scale,
  onFileSelect,
  onDocumentStateChange,
}: PdfViewerProps) {
  const inputRef = useRef<HTMLInputElement>(null)
  const canvasAreaRef = useRef<HTMLDivElement>(null)
  const [isDragging, setIsDragging] = useState(false)

  const { pdfDoc, pageCount, loadStatus, loadError } = usePdfFromBytes(pdfBytes)

  useEffect(() => {
    onDocumentStateChange({ pdfDoc, pageCount, loadStatus, loadError })
  }, [pdfDoc, pageCount, loadStatus, loadError, onDocumentStateChange])

  useEffect(() => {
    if (viewMode !== 'continuous' || !pdfDoc) {
      return
    }

    const pageElement = document.getElementById(`pdf-page-${currentPage}`)
    pageElement?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }, [currentPage, viewMode, pdfDoc])

  useEffect(() => {
    if (viewMode !== 'single' || !pdfDoc) {
      return
    }

    canvasAreaRef.current?.scrollTo({ top: 0, behavior: 'auto' })
  }, [currentPage, viewMode, pdfDoc])

  const openFilePicker = () => {
    inputRef.current?.click()
  }

  const handleInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (file) {
      onFileSelect(file)
    }
    event.target.value = ''
  }

  const handleDragOver = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    setIsDragging(true)
  }

  const handleDragLeave = () => {
    setIsDragging(false)
  }

  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault()
    setIsDragging(false)

    const file = event.dataTransfer.files?.[0]
    if (file) {
      onFileSelect(file)
    }
  }

  const hasPdfBytes = pdfBytes !== null

  return (
    <section className="pdf-viewer" aria-label="Document viewer">
      <input
        ref={inputRef}
        type="file"
        accept="application/pdf,.pdf"
        className="app-header__file-input"
        onChange={handleInputChange}
        aria-hidden="true"
        tabIndex={-1}
      />

      {loadStatus === 'loading' && (
        <div className="pdf-viewer__status pdf-viewer__status--loading" role="status">
          Loading PDF…
        </div>
      )}

      {loadStatus === 'error' && loadError && (
        <div className="pdf-viewer__status pdf-viewer__status--error" role="alert">
          {loadError}
        </div>
      )}

      <div ref={canvasAreaRef} className="pdf-viewer__canvas-area">
        {!hasPdfBytes ? (
          <div
            className={`pdf-viewer__empty${isDragging ? ' is-dragging' : ''}`}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
          >
            <div className="pdf-viewer__empty-icon" aria-hidden="true">
              PDF
            </div>
            <h2 className="pdf-viewer__empty-title">Open a PDF to begin</h2>
            <p className="pdf-viewer__empty-text">
              Drag and drop a local PDF here, or use Open PDF in the header to
              select a file from your computer.
            </p>
            <button type="button" className="btn btn--primary" onClick={openFilePicker}>
              Choose PDF
            </button>
          </div>
        ) : loadStatus === 'loading' ? (
          <div className="pdf-viewer__loading-panel" role="status">
            <p className="pdf-viewer__loading-title">Loading {fileName ?? 'PDF'}…</p>
            <p className="pdf-viewer__loading-text">Parsing document pages in the browser.</p>
          </div>
        ) : loadStatus === 'error' ? (
          <div className="pdf-viewer__error-panel" role="alert">
            <p className="pdf-viewer__error-title">Could not open PDF</p>
            <p className="pdf-viewer__error-text">{loadError ?? 'Unknown error.'}</p>
            <button type="button" className="btn btn--primary" onClick={openFilePicker}>
              Choose another PDF
            </button>
          </div>
        ) : pdfDoc && loadStatus === 'ready' ? (
          <div className="pdf-viewer__pages">
            {viewMode === 'single' ? (
              <PageCanvas
                key={`single-${currentPage}-${scale}`}
                pdfDoc={pdfDoc}
                pageNumber={currentPage}
                scale={scale}
              />
            ) : (
              Array.from({ length: pageCount }, (_, index) => {
                const pageNumber = index + 1
                return (
                  <PageCanvas
                    key={`continuous-${pageNumber}-${scale}`}
                    id={`pdf-page-${pageNumber}`}
                    pdfDoc={pdfDoc}
                    pageNumber={pageNumber}
                    scale={scale}
                  />
                )
              })
            )}
          </div>
        ) : null}
      </div>

      {fileName && loadStatus === 'ready' && (
        <div className="pdf-viewer__footer" aria-live="polite">
          Viewing {fileName}
        </div>
      )}
    </section>
  )
}

import { useCallback, useRef, useState, type ChangeEvent } from 'react'
import EditorToolbar from './components/EditorToolbar'
import PageThumbnailList from './components/PageThumbnailList'
import PdfViewer from './components/PdfViewer'
import ViewerToolbar from './components/ViewerToolbar'
import type { PdfDocumentState } from './hooks/usePdfFromBytes'
import type { ViewMode } from './types/pdf'
import './App.css'

const DEFAULT_SCALE = 1.25

const initialDocumentState: PdfDocumentState = {
  pdfDoc: null,
  pageCount: 0,
  loadStatus: 'idle',
  loadError: null,
}

function isPdfFile(file: File): boolean {
  return file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf')
}

function clampPage(page: number, pageCount: number): number {
  if (pageCount <= 0) {
    return 1
  }
  return Math.min(Math.max(page, 1), pageCount)
}

function App() {
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [fileName, setFileName] = useState<string | null>(null)
  const [pdfBytes, setPdfBytes] = useState<ArrayBuffer | null>(null)
  const [fileReadError, setFileReadError] = useState<string | null>(null)
  const [documentState, setDocumentState] = useState<PdfDocumentState>(initialDocumentState)

  const [currentPage, setCurrentPage] = useState(1)
  const [viewMode, setViewMode] = useState<ViewMode>('continuous')
  const [scale] = useState(DEFAULT_SCALE)
  const [isEditMode, setIsEditMode] = useState(false)

  const { pdfDoc, pageCount, loadStatus, loadError } = documentState
  const hasDocument = loadStatus === 'ready' && pdfDoc !== null

  const handleFileSelect = useCallback(async (file: File) => {
    if (!isPdfFile(file)) {
      window.alert('Please select a PDF file.')
      return
    }

    setFileReadError(null)
    setDocumentState(initialDocumentState)

    try {
      const bytes = await file.arrayBuffer()
      setFileName(file.name)
      setPdfBytes(bytes.slice(0))
      setCurrentPage(1)
      setIsEditMode(false)
    } catch (error) {
      const message =
        error instanceof Error ? error.message : 'Unable to read the selected PDF file.'
      setFileName(null)
      setPdfBytes(null)
      setFileReadError(message)
      setDocumentState({
        pdfDoc: null,
        pageCount: 0,
        loadStatus: 'error',
        loadError: message,
      })
    }
  }, [])

  const handleDocumentStateChange = useCallback((state: PdfDocumentState) => {
    setDocumentState(state)
    setCurrentPage((page) => clampPage(page, state.pageCount))
  }, [])

  const openFilePicker = () => {
    fileInputRef.current?.click()
  }

  const handleHeaderFileChange = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (file) {
      void handleFileSelect(file)
    }
    event.target.value = ''
  }

  const handleQuickDownload = () => {
    if (!pdfBytes || !fileName) {
      return
    }

    const blob = new Blob([pdfBytes], { type: 'application/pdf' })
    const url = URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = fileName
    anchor.click()
    URL.revokeObjectURL(url)
  }

  const goToPage = useCallback(
    (page: number) => {
      setCurrentPage(clampPage(page, pageCount))
    },
    [pageCount],
  )

  const goToPreviousPage = () => {
    goToPage(currentPage - 1)
  }

  const goToNextPage = () => {
    goToPage(currentPage + 1)
  }

  const activeError = fileReadError ?? loadError

  return (
    <div className="app">
      <header className="app-header">
        <div className="app-header__brand">
          <div className="app-header__logo" aria-hidden="true">
            N
          </div>
          <h1 className="app-header__title">Neubus PDF Viewer</h1>
        </div>

        <div className="app-header__file-area">
          <span className="app-header__file-label">Document</span>
          <span
            className={`app-header__file-name${fileName ? '' : ' app-header__file-name--empty'}`}
            title={fileName ?? undefined}
          >
            {fileName ?? 'No file selected'}
          </span>
        </div>

        <div className="app-header__actions">
          <input
            ref={fileInputRef}
            type="file"
            accept="application/pdf,.pdf"
            className="app-header__file-input"
            onChange={handleHeaderFileChange}
            aria-label="Open PDF file"
          />
          <button type="button" className="btn btn--ghost" onClick={openFilePicker}>
            Open PDF
          </button>
          <button
            type="button"
            className="btn btn--primary"
            disabled={!hasDocument}
            onClick={handleQuickDownload}
          >
            Quick Download
          </button>
        </div>
      </header>

      {activeError && (
        <div className="app-error-banner" role="alert">
          {activeError}
        </div>
      )}

      <div className="app-workspace">
        <div className="app-sidebar">
          <PageThumbnailList
            pdfDoc={pdfDoc}
            pageCount={pageCount}
            currentPage={currentPage}
            onPageSelect={goToPage}
          />
        </div>

        <main className="app-main">
          <ViewerToolbar
            disabled={!hasDocument}
            currentPage={currentPage}
            pageCount={pageCount}
            zoomPercent={Math.round(scale * 100)}
            viewMode={viewMode}
            isEditMode={isEditMode}
            onPreviousPage={goToPreviousPage}
            onNextPage={goToNextPage}
            onPageChange={goToPage}
            onViewModeChange={setViewMode}
            onToggleEditMode={() => setIsEditMode((value) => !value)}
          />
          <PdfViewer
            fileName={fileName}
            pdfBytes={pdfBytes}
            currentPage={currentPage}
            viewMode={viewMode}
            scale={scale}
            onFileSelect={handleFileSelect}
            onDocumentStateChange={handleDocumentStateChange}
          />
        </main>

        <aside className="app-edit-panel" aria-label="Edit mode panel">
          <EditorToolbar disabled={!hasDocument || !isEditMode} />

          <div className="edit-panel__header">
            <h2 className="edit-panel__title">Edit mode</h2>
            <p className="edit-panel__subtitle">
              {isEditMode
                ? 'Page editing tools will appear here.'
                : 'Enable edit mode from the viewer toolbar to modify pages.'}
            </p>
          </div>

          <div className="edit-panel__body">
            <div className="edit-panel__placeholder">
              <p className="edit-panel__placeholder-title">Editor panel placeholder</p>
              <p className="edit-panel__placeholder-text">
                This area will host page operations such as rotate, reorder, delete,
                import, extract, and export once editing is implemented.
              </p>
              <ul className="edit-panel__tool-list">
                <li>Rotate selected pages</li>
                <li>Reorder and delete pages</li>
                <li>Import or extract pages</li>
                <li>Export edited PDF</li>
              </ul>
            </div>
          </div>
        </aside>
      </div>
    </div>
  )
}

export default App

import { useEffect, useRef, useState } from 'react'
import type { PDFDocumentProxy } from 'pdfjs-dist'
import { renderPageToCanvas } from '../lib/pdfjs/renderPage'

type PageCanvasProps = {
  pdfDoc: PDFDocumentProxy
  pageNumber: number
  scale: number
  className?: string
  id?: string
}

export default function PageCanvas({
  pdfDoc,
  pageNumber,
  scale,
  className,
  id,
}: PageCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [renderError, setRenderError] = useState<string | null>(null)
  const [isRendering, setIsRendering] = useState(true)

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) {
      return
    }

    let cancelled = false
    setRenderError(null)
    setIsRendering(true)

    renderPageToCanvas(pdfDoc, pageNumber, canvas, scale)
      .then(() => {
        if (!cancelled) {
          setIsRendering(false)
        }
      })
      .catch((error: unknown) => {
        if (!cancelled) {
          const message = error instanceof Error ? error.message : 'Failed to render page.'
          setRenderError(message)
          setIsRendering(false)
        }
      })

    return () => {
      cancelled = true
    }
  }, [pdfDoc, pageNumber, scale])

  if (renderError) {
    return (
      <div className="pdf-page-canvas pdf-page-canvas--error" id={id} role="alert">
        <p className="pdf-page-canvas__error-title">Unable to render page {pageNumber}</p>
        <p className="pdf-page-canvas__error-text">{renderError}</p>
      </div>
    )
  }

  return (
    <div className="pdf-page-canvas-wrap">
      {isRendering && (
        <div className="pdf-page-canvas__loading" aria-hidden={!isRendering}>
          Rendering page {pageNumber}…
        </div>
      )}
      <canvas
        ref={canvasRef}
        className={className ?? 'pdf-page-canvas'}
        id={id}
        aria-label={`Page ${pageNumber}`}
      />
    </div>
  )
}

