export type PageRotation = 0 | 90 | 180 | 270

export type PageSource = {
  id: string
  sourceBytes: ArrayBuffer
  sourcePageIndex: number
  rotation: PageRotation
}

export type EditorStatus = {
  message: string | null
  error: string | null
  isBusy: boolean
}

export const ROTATION_STEPS: PageRotation[] = [0, 90, 180, 270]

export function normalizeRotation(value: number): PageRotation {
  const normalized = ((value % 360) + 360) % 360
  if (normalized === 90 || normalized === 180 || normalized === 270) {
    return normalized
  }
  return 0
}

export function rotateLeft(rotation: PageRotation): PageRotation {
  const index = ROTATION_STEPS.indexOf(rotation)
  return ROTATION_STEPS[(index + 3) % ROTATION_STEPS.length]
}

export function rotateRight(rotation: PageRotation): PageRotation {
  const index = ROTATION_STEPS.indexOf(rotation)
  return ROTATION_STEPS[(index + 1) % ROTATION_STEPS.length]
}

export function createPageId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
}

export function createPagesFromPdf(bytes: ArrayBuffer, pageCount: number): PageSource[] {
  return Array.from({ length: pageCount }, (_, sourcePageIndex) => ({
    id: createPageId(),
    sourceBytes: bytes,
    sourcePageIndex,
    rotation: 0,
  }))
}

import { PDFDocument, degrees } from 'pdf-lib'
import type { PageSource } from '../../types/edits'

async function loadSourceDocument(
  cache: Map<string, PDFDocument>,
  bytes: ArrayBuffer,
): Promise<PDFDocument> {
  const cacheKey = `${bytes.byteLength}:${bytes.byteOffset}`
  let document = cache.get(cacheKey)

  if (!document) {
    document = await PDFDocument.load(bytes.slice(0))
    cache.set(cacheKey, document)
  }

  return document
}

export async function buildPdfBytes(pages: PageSource[]): Promise<Uint8Array> {
  if (pages.length === 0) {
    throw new Error('Cannot build a PDF with no pages.')
  }

  const output = await PDFDocument.create()
  const cache = new Map<string, PDFDocument>()

  for (const page of pages) {
    const sourceDocument = await loadSourceDocument(cache, page.sourceBytes)
    const [copiedPage] = await output.copyPages(sourceDocument, [page.sourcePageIndex])

    if (page.rotation !== 0) {
      copiedPage.setRotation(degrees(page.rotation))
    }

    output.addPage(copiedPage)
  }

  return output.save()
}

export async function getPdfPageCount(bytes: ArrayBuffer): Promise<number> {
  const document = await PDFDocument.load(bytes.slice(0))
  return document.getPageCount()
}

export function uint8ArrayToArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength)
}

export function downloadPdfBytes(bytes: Uint8Array, fileName: string): void {
  const blob = new Blob([bytes], { type: 'application/pdf' })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = fileName
  anchor.click()
  URL.revokeObjectURL(url)
}

export function buildEditedFileName(fileName: string, suffix: string): string {
  const trimmed = fileName.trim()
  if (!trimmed) {
    return `${suffix}.pdf`
  }

  return trimmed.toLowerCase().endsWith('.pdf')
    ? trimmed.replace(/\.pdf$/i, `-${suffix}.pdf`)
    : `${trimmed}-${suffix}.pdf`
}

import { useCallback, useState } from 'react'
import { buildEditedFileName, downloadPdfBytes } from '../lib/fileIO'
import {
  buildPdfBytes,
  getPdfPageCount,
  uint8ArrayToArrayBuffer,
} from '../lib/pdfLib/buildDocument'
import {
  createPageId,
  createPagesFromPdf,
  rotateLeft,
  rotateRight,
  type EditorStatus,
  type PageSource,
} from '../types/edits'

function cloneBytes(bytes: ArrayBuffer): ArrayBuffer {
  return bytes.slice(0)
}

function sortSelectedPages(selectedPages: Set<number>): number[] {
  return [...selectedPages].sort((left, right) => left - right)
}

function clampPage(page: number, pageCount: number): number {
  if (pageCount <= 0) {
    return 1
  }
  return Math.min(Math.max(page, 1), pageCount)
}

const idleStatus: EditorStatus = {
  message: null,
  error: null,
  isBusy: false,
}

export function usePdfEditor() {
  const [fileName, setFileName] = useState<string | null>(null)
  const [originalBytes, setOriginalBytes] = useState<ArrayBuffer | null>(null)
  const [pdfBytes, setPdfBytes] = useState<ArrayBuffer | null>(null)
  const [pages, setPages] = useState<PageSource[]>([])
  const [selectedPages, setSelectedPages] = useState<Set<number>>(new Set())
  const [status, setStatus] = useState<EditorStatus>(idleStatus)
  const [isDirty, setIsDirty] = useState(false)

  const pageCount = pages.length

  const applyPages = useCallback(async (nextPages: PageSource[], message: string) => {
    setStatus({ message: null, error: null, isBusy: true })

    try {
      const output = await buildPdfBytes(nextPages)
      setPages(nextPages)
      setPdfBytes(uint8ArrayToArrayBuffer(output))
      setIsDirty(true)
      setStatus({ message, error: null, isBusy: false })
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Unable to update the edited PDF.'
      setStatus({ message: null, error: errorMessage, isBusy: false })
      throw error
    }
  }, [])

  const openFile = useCallback(async (name: string, bytes: ArrayBuffer) => {
    setStatus({ message: null, error: null, isBusy: true })

    try {
      const copiedBytes = cloneBytes(bytes)
      const count = await getPdfPageCount(copiedBytes)
      const initialPages = createPagesFromPdf(copiedBytes, count)

      setFileName(name)
      setOriginalBytes(copiedBytes)
      setPages(initialPages)
      setPdfBytes(copiedBytes)
      setSelectedPages(new Set())
      setIsDirty(false)
      setStatus({ message: 'Document loaded.', error: null, isBusy: false })
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Unable to prepare the PDF for editing.'
      setFileName(null)
      setOriginalBytes(null)
      setPages([])
      setPdfBytes(null)
      setSelectedPages(new Set())
      setIsDirty(false)
      setStatus({ message: null, error: errorMessage, isBusy: false })
      throw error
    }
  }, [])

  const resetEditor = useCallback(() => {
    setFileName(null)
    setOriginalBytes(null)
    setPdfBytes(null)
    setPages([])
    setSelectedPages(new Set())
    setIsDirty(false)
    setStatus(idleStatus)
  }, [])

  const clearSelection = useCallback(() => {
    setSelectedPages(new Set())
  }, [])

  const togglePageSelection = useCallback((pageNumber: number) => {
    setSelectedPages((current) => {
      const next = new Set(current)
      if (next.has(pageNumber)) {
        next.delete(pageNumber)
      } else {
        next.add(pageNumber)
      }
      return next
    })
  }, [])

  const selectPage = useCallback((pageNumber: number) => {
    setSelectedPages(new Set([pageNumber]))
  }, [])

  const rotateSelected = useCallback(
    async (direction: 'left' | 'right') => {
      if (selectedPages.size === 0) {
        setStatus({ message: null, error: 'Select at least one page to rotate.', isBusy: false })
        return
      }

      const rotate = direction === 'left' ? rotateLeft : rotateRight
      const selected = new Set(selectedPages)

      const nextPages = pages.map((page, index) => {
        if (!selected.has(index + 1)) {
          return page
        }

        return {
          ...page,
          rotation: rotate(page.rotation),
        }
      })

      await applyPages(
        nextPages,
        `Rotated ${selected.size} page${selected.size === 1 ? '' : 's'} ${direction}.`,
      )
    },
    [applyPages, pages, selectedPages],
  )

  const deleteSelected = useCallback(async () => {
    if (selectedPages.size === 0) {
      setStatus({ message: null, error: 'Select at least one page to delete.', isBusy: false })
      return
    }

    if (selectedPages.size >= pages.length) {
      setStatus({
        message: null,
        error: 'At least one page must remain in the document.',
        isBusy: false,
      })
      return
    }

    const selected = new Set(selectedPages)
    const nextPages = pages.filter((_, index) => !selected.has(index + 1))

    setSelectedPages(new Set())
    await applyPages(
      nextPages,
      `Deleted ${selected.size} page${selected.size === 1 ? '' : 's'}.`,
    )
  }, [applyPages, pages, selectedPages])

  const moveSelected = useCallback(
    async (direction: 'up' | 'down') => {
      if (selectedPages.size === 0) {
        setStatus({ message: null, error: 'Select at least one page to move.', isBusy: false })
        return
      }

      const selected = sortSelectedPages(selectedPages)
      const nextPages = [...pages]

      if (direction === 'up') {
        const firstIndex = selected[0] - 1
        if (firstIndex <= 0) {
          setStatus({ message: 'Selected pages are already at the top.', error: null, isBusy: false })
          return
        }

        const swapIndex = firstIndex - 1
        ;[nextPages[swapIndex], nextPages[firstIndex]] = [nextPages[firstIndex], nextPages[swapIndex]]
        setSelectedPages(new Set(selected.map((page) => page - 1)))
      } else {
        const lastIndex = selected[selected.length - 1] - 1
        if (lastIndex >= nextPages.length - 1) {
          setStatus({
            message: 'Selected pages are already at the bottom.',
            error: null,
            isBusy: false,
          })
          return
        }

        const swapIndex = lastIndex + 1
        ;[nextPages[lastIndex], nextPages[swapIndex]] = [nextPages[swapIndex], nextPages[lastIndex]]
        setSelectedPages(new Set(selected.map((page) => page + 1)))
      }

      await applyPages(
        nextPages,
        `Moved ${selected.length} page${selected.length === 1 ? '' : 's'} ${direction}.`,
      )
    },
    [applyPages, pages, selectedPages],
  )

  const importPdf = useCallback(
    async (bytes: ArrayBuffer) => {
      if (pages.length === 0) {
        setStatus({ message: null, error: 'Open a PDF before importing pages.', isBusy: false })
        return
      }

      setStatus({ message: null, error: null, isBusy: true })

      try {
        const copiedBytes = cloneBytes(bytes)
        const importPageCount = await getPdfPageCount(copiedBytes)
        const importedPages: PageSource[] = Array.from({ length: importPageCount }, (_, index) => ({
          id: createPageId(),
          sourceBytes: copiedBytes,
          sourcePageIndex: index,
          rotation: 0,
        }))

        await applyPages(
          [...pages, ...importedPages],
          `Imported ${importPageCount} page${importPageCount === 1 ? '' : 's'}.`,
        )
      } catch (error) {
        const errorMessage =
          error instanceof Error ? error.message : 'Unable to import the selected PDF.'
        setStatus({ message: null, error: errorMessage, isBusy: false })
      }
    },
    [applyPages, pages],
  )

  const extractSelected = useCallback(async () => {
    if (selectedPages.size === 0) {
      setStatus({ message: null, error: 'Select at least one page to extract.', isBusy: false })
      return
    }

    setStatus({ message: null, error: null, isBusy: true })

    try {
      const selected = sortSelectedPages(selectedPages)
      const extractedPages = selected.map((pageNumber) => pages[pageNumber - 1])
      const output = await buildPdfBytes(extractedPages)
      const downloadName = buildEditedFileName(fileName ?? 'document', 'extract')
      downloadPdfBytes(output, downloadName)
      setStatus({
        message: `Extracted ${selected.length} page${selected.length === 1 ? '' : 's'}.`,
        error: null,
        isBusy: false,
      })
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Unable to extract the selected pages.'
      setStatus({ message: null, error: errorMessage, isBusy: false })
    }
  }, [fileName, pages, selectedPages])

  const exportEdited = useCallback(async () => {
    if (pages.length === 0 || !pdfBytes) {
      setStatus({ message: null, error: 'Open a PDF before exporting.', isBusy: false })
      return
    }

    setStatus({ message: null, error: null, isBusy: true })

    try {
      const output = await buildPdfBytes(pages)
      const downloadName = isDirty
        ? buildEditedFileName(fileName ?? 'document', 'edited')
        : (fileName ?? 'document.pdf')
      downloadPdfBytes(output, downloadName)
      setStatus({ message: 'Edited PDF downloaded.', error: null, isBusy: false })
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Unable to export the edited PDF.'
      setStatus({ message: null, error: errorMessage, isBusy: false })
    }
  }, [fileName, isDirty, pages, pdfBytes])

  const downloadCurrent = useCallback(async () => {
    await exportEdited()
  }, [exportEdited])

  return {
    fileName,
    originalBytes,
    pdfBytes,
    pages,
    pageCount,
    selectedPages,
    status,
    isDirty,
    openFile,
    resetEditor,
    clearSelection,
    togglePageSelection,
    selectPage,
    rotateSelected,
    deleteSelected,
    moveSelected,
    importPdf,
    extractSelected,
    exportEdited,
    downloadCurrent,
    clampPage,
  }
}

import { PDFDocument, degrees } from 'pdf-lib'
import type { PageSource } from '../../types/edits'

export async function buildPdfBytes(pages: PageSource[]): Promise<Uint8Array> {
  if (pages.length === 0) {
    throw new Error('Cannot build a PDF with no pages.')
  }

  const output = await PDFDocument.create()
  const cache = new Map<ArrayBuffer, PDFDocument>()

  for (const page of pages) {
    let sourceDocument = cache.get(page.sourceBytes)

    if (!sourceDocument) {
      sourceDocument = await PDFDocument.load(page.sourceBytes.slice(0))
      cache.set(page.sourceBytes, sourceDocument)
    }

    const [copiedPage] = await output.copyPages(sourceDocument, [page.sourcePageIndex])

    if (page.rotation !== 0) {
      copiedPage.setRotation(degrees(page.rotation))
    }

    output.addPage(copiedPage)
  }

  return output.save()
}

export async function getPdfPageCount(bytes: ArrayBuffer): Promise<number> {
  const document = await PDFDocument.load(bytes.slice(0))
  return document.getPageCount()
}

export function uint8ArrayToArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength)
}

import type { PDFDocumentProxy } from 'pdfjs-dist'
import PageCanvas from './PageCanvas'

type PageThumbnailListProps = {
  pdfDoc?: PDFDocumentProxy | null
  pageCount?: number
  currentPage?: number
  selectedPages?: Set<number>
  isEditMode?: boolean
  onPageSelect?: (page: number) => void
  onPageToggleSelect?: (page: number) => void
}

const THUMBNAIL_SCALE = 0.18

export default function PageThumbnailList({
  pdfDoc = null,
  pageCount = 0,
  currentPage = 1,
  selectedPages = new Set<number>(),
  isEditMode = false,
  onPageSelect,
  onPageToggleSelect,
}: PageThumbnailListProps) {
  const hasDocument = pageCount > 0 && pdfDoc !== null

  const handleClick = (pageNumber: number) => {
    onPageSelect?.(pageNumber)

    if (isEditMode) {
      onPageToggleSelect?.(pageNumber)
    }
  }

  return (
    <aside className="thumbnail-list" aria-label="Page thumbnails">
      <div className="thumbnail-list__header">
        Pages
        {isEditMode && hasDocument && (
          <span className="thumbnail-list__hint">Click to select</span>
        )}
      </div>
      <div className="thumbnail-list__body">
        {!hasDocument ? (
          <p className="thumbnail-list__empty">
            Open a PDF to see page thumbnails.
          </p>
        ) : (
          Array.from({ length: pageCount }, (_, index) => {
            const pageNumber = index + 1
            const isActive = pageNumber === currentPage
            const isSelected = selectedPages.has(pageNumber)

            return (
              <button
                key={`page-${pageNumber}`}
                type="button"
                className={`thumbnail-item${isActive ? ' is-active' : ''}${isSelected ? ' is-selected' : ''}`}
                onClick={() => handleClick(pageNumber)}
                aria-label={`Page ${pageNumber}${isSelected ? ', selected' : ''}`}
                aria-current={isActive ? 'page' : undefined}
                aria-pressed={isEditMode ? isSelected : undefined}
              >
                <div className="thumbnail-item__preview">
                  <PageCanvas
                    pdfDoc={pdfDoc}
                    pageNumber={pageNumber}
                    scale={THUMBNAIL_SCALE}
                    className="thumbnail-item__canvas"
                  />
                </div>
                <span className="thumbnail-item__label">{pageNumber}</span>
              </button>
            )
          })
        )}
      </div>
    </aside>
  )
}

import { useCallback, useEffect, useRef, useState, type ChangeEvent } from 'react'
import EditorPanel from './components/EditorPanel'
import EditorToolbar from './components/EditorToolbar'
import PageThumbnailList from './components/PageThumbnailList'
import PdfViewer from './components/PdfViewer'
import ViewerToolbar from './components/ViewerToolbar'
import { usePdfEditor } from './hooks/usePdfEditor'
import type { PdfDocumentState } from './hooks/usePdfFromBytes'
import type { ViewMode } from './types/pdf'
import './App.css'

const DEFAULT_SCALE = 1.25

const initialDocumentState: PdfDocumentState = {
  pdfDoc: null,
  pageCount: 0,
  loadStatus: 'idle',
  loadError: null,
}

function isPdfFile(file: File): boolean {
  return file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf')
}

function App() {
  const fileInputRef = useRef<HTMLInputElement>(null)
  const importInputRef = useRef<HTMLInputElement>(null)

  const editor = usePdfEditor()
  const {
    fileName,
    pdfBytes,
    pageCount: editorPageCount,
    selectedPages,
    status: editorStatus,
    isDirty,
    openFile,
    resetEditor,
    clearSelection,
    togglePageSelection,
    rotateSelected,
    deleteSelected,
    moveSelected,
    importPdf,
    extractSelected,
    exportEdited,
    downloadCurrent,
    clampPage,
  } = editor

  const [fileReadError, setFileReadError] = useState<string | null>(null)
  const [documentState, setDocumentState] = useState<PdfDocumentState>(initialDocumentState)
  const [currentPage, setCurrentPage] = useState(1)
  const [viewMode, setViewMode] = useState<ViewMode>('continuous')
  const [scale] = useState(DEFAULT_SCALE)
  const [isEditMode, setIsEditMode] = useState(false)

  const { pdfDoc, pageCount: viewerPageCount, loadStatus, loadError } = documentState
  const pageCount = viewerPageCount || editorPageCount
  const hasDocument = editorPageCount > 0 && (loadStatus === 'ready' || loadStatus === 'loading')

  useEffect(() => {
    setCurrentPage((page) => clampPage(page, editorPageCount))
  }, [clampPage, editorPageCount])

  const handleFileSelect = useCallback(
    async (file: File) => {
      if (!isPdfFile(file)) {
        window.alert('Please select a PDF file.')
        return
      }

      setFileReadError(null)
      setDocumentState(initialDocumentState)
      setIsEditMode(false)

      try {
        const bytes = await file.arrayBuffer()
        await openFile(file.name, bytes)
        setCurrentPage(1)
      } catch (error) {
        const message =
          error instanceof Error ? error.message : 'Unable to read the selected PDF file.'
        resetEditor()
        setFileReadError(message)
        setDocumentState({
          pdfDoc: null,
          pageCount: 0,
          loadStatus: 'error',
          loadError: message,
        })
      }
    },
    [openFile, resetEditor],
  )

  const handleDocumentStateChange = useCallback(
    (state: PdfDocumentState) => {
      setDocumentState(state)
      setCurrentPage((page) => clampPage(page, state.pageCount || editorPageCount))
    },
    [clampPage, editorPageCount],
  )

  const openFilePicker = () => {
    fileInputRef.current?.click()
  }

  const openImportPicker = () => {
    importInputRef.current?.click()
  }

  const handleHeaderFileChange = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (file) {
      void handleFileSelect(file)
    }
    event.target.value = ''
  }

  const handleImportFileChange = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (!file) {
      return
    }

    if (!isPdfFile(file)) {
      window.alert('Please select a PDF file to import.')
      event.target.value = ''
      return
    }

    void file.arrayBuffer().then((bytes) => importPdf(bytes))
    event.target.value = ''
  }

  const handleToggleEditMode = () => {
    setIsEditMode((value) => {
      if (value) {
        clearSelection()
      }
      return !value
    })
  }

  const handlePageSelect = (page: number) => {
    setCurrentPage(clampPage(page, pageCount))
  }

  const handlePageToggleSelect = (page: number) => {
    togglePageSelection(page)
  }

  const goToPage = useCallback(
    (page: number) => {
      setCurrentPage(clampPage(page, pageCount))
    },
    [clampPage, pageCount],
  )

  const goToPreviousPage = () => {
    goToPage(currentPage - 1)
  }

  const goToNextPage = () => {
    goToPage(currentPage + 1)
  }

  const runEditorAction = (action: () => Promise<void>) => {
    void action().catch(() => {
      // Errors are surfaced through editor status state.
    })
  }

  const activeError = fileReadError ?? loadError ?? editorStatus.error

  return (
    <div className="app">
      <header className="app-header">
        <div className="app-header__brand">
          <div className="app-header__logo" aria-hidden="true">
            N
          </div>
          <h1 className="app-header__title">Neubus PDF Viewer</h1>
        </div>

        <div className="app-header__file-area">
          <span className="app-header__file-label">Document</span>
          <span
            className={`app-header__file-name${fileName ? '' : ' app-header__file-name--empty'}`}
            title={fileName ?? undefined}
          >
            {fileName ?? 'No file selected'}
            {isDirty ? ' (edited)' : ''}
          </span>
        </div>

        <div className="app-header__actions">
          <input
            ref={fileInputRef}
            type="file"
            accept="application/pdf,.pdf"
            className="app-header__file-input"
            onChange={handleHeaderFileChange}
            aria-label="Open PDF file"
          />
          <input
            ref={importInputRef}
            type="file"
            accept="application/pdf,.pdf"
            className="app-header__file-input"
            onChange={handleImportFileChange}
            aria-label="Import PDF file"
          />
          <button type="button" className="btn btn--ghost" onClick={openFilePicker}>
            Open PDF
          </button>
          <button
            type="button"
            className="btn btn--primary"
            disabled={!hasDocument || editorStatus.isBusy}
            onClick={() => runEditorAction(downloadCurrent)}
          >
            Quick Download
          </button>
        </div>
      </header>

      {activeError && (
        <div className="app-error-banner" role="alert">
          {activeError}
        </div>
      )}

      {editorStatus.message && !activeError && (
        <div className="app-status-banner" role="status">
          {editorStatus.message}
        </div>
      )}

      <div className="app-workspace">
        <div className="app-sidebar">
          <PageThumbnailList
            pdfDoc={pdfDoc}
            pageCount={pageCount}
            currentPage={currentPage}
            selectedPages={selectedPages}
            isEditMode={isEditMode}
            onPageSelect={handlePageSelect}
            onPageToggleSelect={handlePageToggleSelect}
          />
        </div>

        <main className="app-main">
          <ViewerToolbar
            disabled={!hasDocument}
            currentPage={currentPage}
            pageCount={pageCount}
            zoomPercent={Math.round(scale * 100)}
            viewMode={viewMode}
            isEditMode={isEditMode}
            onPreviousPage={goToPreviousPage}
            onNextPage={goToNextPage}
            onPageChange={goToPage}
            onViewModeChange={setViewMode}
            onToggleEditMode={handleToggleEditMode}
          />
          <PdfViewer
            fileName={fileName}
            pdfBytes={pdfBytes}
            currentPage={currentPage}
            viewMode={viewMode}
            scale={scale}
            onFileSelect={handleFileSelect}
            onDocumentStateChange={handleDocumentStateChange}
          />
        </main>

        <aside className="app-edit-panel" aria-label="Edit mode panel">
          <EditorToolbar
            disabled={!hasDocument || !isEditMode || editorStatus.isBusy}
            onRotateLeft={() => runEditorAction(() => rotateSelected('left'))}
            onRotateRight={() => runEditorAction(() => rotateSelected('right'))}
            onDelete={() => runEditorAction(deleteSelected)}
            onImport={openImportPicker}
            onExtract={() => runEditorAction(extractSelected)}
          />

          <EditorPanel
            disabled={!hasDocument || !isEditMode}
            isEditMode={isEditMode}
            selectedCount={selectedPages.size}
            pageCount={pageCount}
            isDirty={isDirty}
            isBusy={editorStatus.isBusy}
            statusMessage={editorStatus.message}
            statusError={editorStatus.error}
            onMoveUp={() => runEditorAction(() => moveSelected('up'))}
            onMoveDown={() => runEditorAction(() => moveSelected('down'))}
            onExport={() => runEditorAction(exportEdited)}
          />
        </aside>
      </div>
    </div>
  )
}

export default App

