export const MIN_ZOOM_SCALE = 0.25
export const MAX_ZOOM_SCALE = 3
export const DEFAULT_ZOOM_SCALE = 1.25
export const ZOOM_STEP_FACTOR = 1.25
export const VIEWER_CANVAS_PADDING_PX = 48

export function clampZoomScale(scale: number): number {
  return Math.min(MAX_ZOOM_SCALE, Math.max(MIN_ZOOM_SCALE, scale))
}

export function zoomIn(scale: number, factor = ZOOM_STEP_FACTOR): number {
  return clampZoomScale(scale * factor)
}

export function zoomOut(scale: number, factor = ZOOM_STEP_FACTOR): number {
  return clampZoomScale(scale / factor)
}

export function computeFitWidthScale(pageWidth: number, containerWidth: number): number {
  if (pageWidth <= 0 || containerWidth <= 0) {
    return DEFAULT_ZOOM_SCALE
  }

  return clampZoomScale(containerWidth / pageWidth)
}

export function computeFitPageScale(
  pageWidth: number,
  pageHeight: number,
  containerWidth: number,
  containerHeight: number,
): number {
  if (pageWidth <= 0 || pageHeight <= 0 || containerWidth <= 0 || containerHeight <= 0) {
    return DEFAULT_ZOOM_SCALE
  }

  const widthScale = containerWidth / pageWidth
  const heightScale = containerHeight / pageHeight
  return clampZoomScale(Math.min(widthScale, heightScale))
}

export function zoomScaleToPercent(scale: number): number {
  return Math.round(scale * 100)
}

import type { PDFDocumentProxy } from 'pdfjs-dist'

export type PageDimensions = {
  width: number
  height: number
}

export async function getPageDimensions(
  pdfDoc: PDFDocumentProxy,
  pageNumber: number,
): Promise<PageDimensions> {
  const page = await pdfDoc.getPage(pageNumber)
  const viewport = page.getViewport({ scale: 1 })

  return {
    width: viewport.width,
    height: viewport.height,
  }
}

import { describe, expect, it } from 'vitest'
import {
  clampZoomScale,
  computeFitPageScale,
  computeFitWidthScale,
  DEFAULT_ZOOM_SCALE,
  MAX_ZOOM_SCALE,
  MIN_ZOOM_SCALE,
  zoomIn,
  zoomOut,
  zoomScaleToPercent,
} from './zoom'

describe('zoom utilities', () => {
  it('clamps scale to configured bounds', () => {
    expect(clampZoomScale(0.1)).toBe(MIN_ZOOM_SCALE)
    expect(clampZoomScale(5)).toBe(MAX_ZOOM_SCALE)
    expect(clampZoomScale(1.5)).toBe(1.5)
  })

  it('steps zoom in and out', () => {
    expect(zoomIn(1)).toBeGreaterThan(1)
    expect(zoomOut(1)).toBeLessThan(1)
  })

  it('computes fit-to-width scale from page and container width', () => {
    expect(computeFitWidthScale(800, 400)).toBe(0.5)
    expect(computeFitWidthScale(400, 800)).toBe(2)
  })

  it('computes fit-to-page scale using the smaller of width and height ratios', () => {
    expect(computeFitPageScale(800, 1200, 400, 600)).toBe(0.5)
    expect(computeFitPageScale(400, 400, 800, 200)).toBe(0.5)
  })

  it('falls back to the default scale for invalid dimensions', () => {
    expect(computeFitWidthScale(0, 400)).toBe(DEFAULT_ZOOM_SCALE)
    expect(computeFitPageScale(0, 0, 400, 600)).toBe(DEFAULT_ZOOM_SCALE)
  })

  it('converts scale to a rounded percentage', () => {
    expect(zoomScaleToPercent(1.25)).toBe(125)
  })
})

import { useCallback, useState, type RefObject } from 'react'
import type { PDFDocumentProxy } from 'pdfjs-dist'
import { getPageDimensions } from '../lib/pdfjs/getPageDimensions'
import {
  clampZoomScale,
  computeFitPageScale,
  computeFitWidthScale,
  DEFAULT_ZOOM_SCALE,
  VIEWER_CANVAS_PADDING_PX,
  zoomIn,
  zoomOut,
  zoomScaleToPercent,
} from '../lib/viewport/zoom'

type UseViewerZoomOptions = {
  canvasAreaRef: RefObject<HTMLDivElement | null>
  pdfDoc: PDFDocumentProxy | null
  currentPage: number
  hasDocument: boolean
}

export function useViewerZoom({
  canvasAreaRef,
  pdfDoc,
  currentPage,
  hasDocument,
}: UseViewerZoomOptions) {
  const [zoomScale, setZoomScale] = useState(DEFAULT_ZOOM_SCALE)

  const resetZoom = useCallback(() => {
    setZoomScale(DEFAULT_ZOOM_SCALE)
  }, [])

  const handleZoomIn = useCallback(() => {
    if (!hasDocument) {
      return
    }

    setZoomScale((current) => zoomIn(current))
  }, [hasDocument])

  const handleZoomOut = useCallback(() => {
    if (!hasDocument) {
      return
    }

    setZoomScale((current) => zoomOut(current))
  }, [hasDocument])

  const applyFitScale = useCallback(
    async (computeScale: (pageWidth: number, pageHeight: number) => number) => {
      if (!hasDocument || !pdfDoc || !canvasAreaRef.current) {
        return
      }

      const container = canvasAreaRef.current
      const availableWidth = Math.max(container.clientWidth - VIEWER_CANVAS_PADDING_PX, 1)
      const availableHeight = Math.max(container.clientHeight - VIEWER_CANVAS_PADDING_PX, 1)
      const { width, height } = await getPageDimensions(pdfDoc, currentPage)
      setZoomScale(computeScale(width, height))
    },
    [canvasAreaRef, currentPage, hasDocument, pdfDoc],
  )

  const handleFitWidth = useCallback(async () => {
    await applyFitScale((pageWidth) => {
      const container = canvasAreaRef.current
      if (!container) {
        return DEFAULT_ZOOM_SCALE
      }

      const availableWidth = Math.max(container.clientWidth - VIEWER_CANVAS_PADDING_PX, 1)
      return computeFitWidthScale(pageWidth, availableWidth)
    })
  }, [applyFitScale, canvasAreaRef])

  const handleFitPage = useCallback(async () => {
    await applyFitScale((pageWidth, pageHeight) => {
      const container = canvasAreaRef.current
      if (!container) {
        return DEFAULT_ZOOM_SCALE
      }

      const availableWidth = Math.max(container.clientWidth - VIEWER_CANVAS_PADDING_PX, 1)
      const availableHeight = Math.max(container.clientHeight - VIEWER_CANVAS_PADDING_PX, 1)
      return computeFitPageScale(pageWidth, pageHeight, availableWidth, availableHeight)
    })
  }, [applyFitScale, canvasAreaRef])

  return {
    zoomScale: clampZoomScale(zoomScale),
    zoomPercent: zoomScaleToPercent(zoomScale),
    resetZoom,
    handleZoomIn,
    handleZoomOut,
    handleFitWidth,
    handleFitPage,
  }
}

