  if (!container) {
    return null
  }

  return {
    width: Math.max(container.clientWidth - VIEWER_CANVAS_PADDING_PX, 1),
    height: Math.max(container.clientHeight - VIEWER_CANVAS_PADDING_PX, 1),
  }
}, [canvasAreaRef])

